// Independent pure capability/draft tests and unshown WPF layout tests.
// All sessions/sensors are synthetic; no native process, HWND or installed assets.
using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Web.Script.Serialization;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using RogControl;
internal static class LcdMonitorGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;static int Count;
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);Count++;}
 static object Get(MainWindow window,string field){return typeof(MainWindow).GetField(field,Hidden).GetValue(window);}
 static void Set(MainWindow window,string field,object value){typeof(MainWindow).GetField(field,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string method,params object[] args){return typeof(MainWindow).GetMethod(method,Hidden).Invoke(window,args);}
 static Dictionary<string,object> Obj(params object[] fields){var map=new Dictionary<string,object>();for(int i=0;i<fields.Length;i+=2)map[(string)fields[i]]=fields[i+1];return map;}
 static Dictionary<string,object> Cap(int index,int type,string name,string native=null,string fallback=null){return Obj("id","sensor-"+index,"nativeId",native??(index+1).ToString(),"nativeType",type,"name",name,"defaultName",fallback??name,"value",999,"valueReadbackConfirmed",false);}
 static Dictionary<string,object> Snapshot(){return Obj("deviceId","7299","readbackConfirmed",true,"deviceAlive",true,"hardwareMonitorWritable",true,"hardwareSensors",new object[]{Cap(0,0,"CPU voltage"),Cap(1,1,"CPU temperature"),Cap(2,2,"CPU Fan"),Cap(3,4,"CPU frequency"),Cap(4,4,"GPU frequency"),Cap(5,5,"CPU utilization")});}
 static bool Valid(LcdMonitorDraft model,Dictionary<string,object> snapshot,int background,int count){string[] ids;object token;return model.TryBuild(snapshot,background,count,out ids,out token);}
 static void Choose(LcdMonitorDraft model,Dictionary<string,object> snapshot,int index,int type,int sensor){model.SetCategory(snapshot,index,type);Check(model.Select(snapshot,index,"sensor-"+sensor),"synthetic exact capability selection");}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){yield return node;foreach(object item in LogicalTreeHelper.GetChildren(node)){var child=item as DependencyObject;if(child!=null)foreach(var next in Walk(child))yield return next;}}
 static List<FrameworkElement> Nodes(MainWindow window){return Walk((DependencyObject)Get(window,"content")).OfType<FrameworkElement>().ToList();}
 static T Tagged<T>(MainWindow window,string tag)where T:FrameworkElement{return Nodes(window).OfType<T>().Single(element=>Convert.ToString(element.Tag)==tag);}
 static void NoNative(MainWindow window){Check(new WindowInteropHelper(window).Handle==IntPtr.Zero,"no HWND created");foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(field=>field.FieldType==typeof(WorkerClient)))Check(typeof(WorkerClient).GetField("process",Hidden).GetValue((WorkerClient)field.GetValue(window))==null,"no worker "+field.Name);Check(((Dictionary<string,WorkerClient>)Get(window,"sdkWorkers")).Count==0,"no SDK client created");}
 static void Render(MainWindow window,int width){Invoke(window,"ShowPage","device:motherboard");((ScrollViewer)Get(window,"pageScroll")).ScrollToTop();var frame=(FrameworkElement)window.Content;int height=width==1538?826:726;frame.Measure(new Size(width,height));frame.Arrange(new Rect(0,0,width,height));frame.UpdateLayout();}
 static void Pure(){var snapshot=Snapshot();object session=new object();var model=new LcdMonitorDraft();model.Bind(snapshot,session,()=>session);Check(model.IsCurrent(snapshot),"fresh exact snapshot/session");Check(model.Sensors(snapshot).Count==5,"unsupported type5 is not guessed into category");model.Resize(1);Check(!Valid(model,snapshot,8,1),"initial sensor unselected");Choose(model,snapshot,0,0,0);Check(Valid(model,snapshot,8,1),"valid single");model.Resize(3);Check(!Valid(model,snapshot,8,3),"added rows remain unselected");Choose(model,snapshot,1,1,1);Choose(model,snapshot,2,2,2);string[] ids;object returned;Check(model.TryBuild(snapshot,8,3,out ids,out returned)&&ids.SequenceEqual(new[]{"sensor-0","sensor-1","sensor-2"})&&Object.ReferenceEquals(returned,session),"source row order and bound token retained");model.SetCategory(snapshot,2,0);Check(!Valid(model,snapshot,8,3),"category change clears previous sensor");Check(!model.Select(snapshot,2,"sensor-2"),"cross-category sensor rejected");Check(model.Select(snapshot,2,"sensor-0")&&!Valid(model,snapshot,8,3),"duplicate sensor identity rejected");Choose(model,snapshot,2,2,2);model.Resize(5);Choose(model,snapshot,3,4,3);Choose(model,snapshot,4,4,4);Check(Valid(model,snapshot,11,5),"five distinct capabilities incl two frequencies");Check(!Valid(model,snapshot,8,5),"first backgrounds limited to3");Check(!Valid(model,snapshot,7,5)&&!Valid(model,snapshot,12,5)&&!Valid(model,snapshot,11,0)&&!Valid(model,snapshot,11,6),"invalid layout rejected");Check(!model.Select(snapshot,4,"sensor-not-present"),"unknown opaque ID rejected");Choose(model,snapshot,4,4,4);
  var clone=new Dictionary<string,object>(snapshot);Check(!model.IsCurrent(clone)&&!Valid(model,clone,11,5),"same text IDs in another read cannot reuse selection");session=new object();Check(!model.IsCurrent(snapshot)&&model.Sensors(snapshot).Count==0&&!Valid(model,snapshot,11,5),"worker restart invalidates caps and selection");model.Bind(snapshot,session,()=>session);Check(model.Rows.Count==0,"new read clears prior selection");model.Resize(1);Choose(model,snapshot,0,0,0);((Dictionary<string,object>)((object[])snapshot["hardwareSensors"])[0])["name"]="Renamed";Check(!Valid(model,snapshot,8,1)&&model.Sensors(snapshot).Count==0,"in-place capability mutation invalidates fingerprint");model.Bind(snapshot,session,()=>session);model.Resize(1);Choose(model,snapshot,0,0,0);model.Bind(snapshot,new object(),()=>session);Check(!model.IsCurrent(snapshot),"mismatched session provider rejected");model.Bind(snapshot,session,()=>{throw new InvalidOperationException("synthetic expired provider");});Check(!model.IsCurrent(snapshot),"failed provider cannot authorize");model.Clear();Check(model.Rows.Count==0&&!Valid(model,snapshot,8,1),"clear removes all IDs/token");
  var bad=Snapshot();bad["readbackConfirmed"]=false;model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"unconfirmed snapshot rejected");bad=Snapshot();bad["deviceAlive"]=false;model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"offline rejected");bad=Snapshot();bad["deviceId"]="7571";model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"unverified GUI family not widened");bad=Snapshot();bad["hardwareMonitorWritable"]=false;model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"missing capability rejected");bad=Snapshot();bad["hardwareSensors"]=new object[]{Cap(0,0,"A"),Cap(0,1,"B")};model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"duplicate opaque identity rejected");bad=Snapshot();bad["hardwareSensors"]=new object[]{Cap(0,0,"A","-1")};model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"malformed native identity rejected");bad=Snapshot();bad["hardwareSensors"]=new object[]{Cap(0,5,"CPU utilization")};model.Bind(bad,session,()=>session);Check(!model.IsCurrent(bad),"only unknown category cannot become selectable");
  var alias=Snapshot();alias["hardwareSensors"]=new object[]{Cap(0,0,"Voltage A","1","Same hardware"),Cap(1,0,"Voltage B","1","Same hardware")};model.Bind(alias,session,()=>session);model.Resize(2);Choose(model,alias,0,0,0);Choose(model,alias,1,0,1);Check(!Valid(model,alias,11,2),"different opaque aliases of same hardware cannot repeat");
 }
 [STAThread]public static int Main(){try{Pure();new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);window.Left=10;window.Top=20;Set(window,"lcdMonitorLocalImages",false);Set(window,"lcdMonitorMode",true);Set(window,"originalMotherboardTab","5\" LCD Display");var snapshots=(Dictionary<string,Dictionary<string,object>>)Get(window,"sdkSnapshots");var snapshot=Snapshot();object session=new object();snapshots["lcd:7299"]=snapshot;Invoke(window,"BindLcdMonitorRead",snapshot,session,(Func<object>)(()=>session));var draft=(LcdMonitorDraft)Get(window,"lcdMonitorDraft");
  foreach(int width in new[]{1538,1180}){Render(window,width);var nodes=Nodes(window);var backgrounds=nodes.OfType<Button>().Where(button=>Convert.ToString(button.Tag).StartsWith("lcdMonitor:background:")).ToArray();Check(backgrounds.Length==4&&backgrounds.All(button=>button.Width==72&&button.Height==125),"four72x125 backgrounds");Check(backgrounds.Take(3).All(button=>button.Margin.Right==20),"20px gaps");var info=Tagged<ComboBox>(window,"lcdMonitor:infoCount");Check(info.ActualWidth==320&&info.Height==34&&info.Items.Cast<string>().SequenceEqual(new[]{"Single Info","Dual Info","Triple Info"}),"native count dropdown");Check(Tagged<ComboBox>(window,"lcdMonitor:category:0").ActualWidth==264,"category264");Check(Tagged<ComboBox>(window,"lcdMonitor:category:0").Items.OfType<ComboBoxItem>().Select(item=>Convert.ToString(item.Content)).SequenceEqual(new[]{"—","Voltage","Temperature","Fan Speed","Frequency"}),"four categories from current caps");var sensorBox=Tagged<ComboBox>(window,"lcdMonitor:sensor:0");Check(sensorBox.SelectedIndex==0&&!sensorBox.IsEnabled,"no default CPU sensor");Check(sensorBox.ActualWidth>=418,"sensor remainder preserves native width");var inner=nodes.OfType<ScrollViewer>().FirstOrDefault(viewer=>viewer.HorizontalScrollBarVisibility==ScrollBarVisibility.Auto);Check(inner!=null,"monitor body horizontal viewer exists");if(width==1180){Check(inner.ScrollableWidth>300,"narrow body can scroll");inner.ScrollToRightEnd();((ScrollViewer)Get(window,"pageScroll")).ScrollToBottom();((FrameworkElement)window.Content).UpdateLayout();}Rect bounds=sensorBox.TransformToAncestor((FrameworkElement)window.Content).TransformBounds(new Rect(0,0,sensorBox.ActualWidth,sensorBox.ActualHeight));Check(bounds.Left>=248&&bounds.Right<=width-21,"right sensor choice reachable at both widths");NoNative(window);}
