  Invoke(window,"QueuePageRead","device:motherboard");Check((string)Get(window,"pendingPageRead")=="device:motherboard"&&!(bool)Get(window,"pendingPageReadMayPreserveDraft"),"page entry remains eligible for fresh read");Invoke(window,"QueuePageRead","device:motherboard");Check((string)Get(window,"pendingPageRead")=="device:motherboard"&&!(bool)Get(window,"pendingPageReadMayPreserveDraft"),"editing before entry read begins cannot cancel that fresh read");Set(window,"pendingPageRead","");Invoke(window,"QueuePageRead","device:motherboard");Check((string)Get(window,"pendingPageRead")==""&&draft.Rows[0].Category==0&&draft.Rows[0].SensorId==null,"same-view partial category draft pauses old auto-read");Check(draft.Select(snapshot,0,"sensor-0"),"queue fixture complete selection");Invoke(window,"QueuePageRead","device:motherboard");Check((string)Get(window,"pendingPageRead")==""&&draft.Rows[0].SensorId=="sensor-0","same-bound selected draft preserved beyond cooldown");Set(window,"pendingPageRead","device:motherboard");Set(window,"pendingPageReadMayPreserveDraft",true);Invoke(window,"QueuePageRead","device:motherboard");Check((string)Get(window,"pendingPageRead")==""&&draft.Rows[0].SensorId=="sensor-0","an older same-view pending read is cancelled when editing begins");
